// ============ PARSER ============

struct Parser {
    tokens: Vec<Token>,
    position: usize,
    filename: String,
}

impl Parser {
    fn new(tokens: Vec<Token>, filename: &str) -> Self {
        Parser {
            tokens,
            position: 0,
            filename: filename.to_string(),
        }
    }

    fn current_token(&self) -> &Token {
        &self.tokens[self.position.min(self.tokens.len() - 1)]
    }

    fn peek_token(&self, offset: usize) -> &Token {
        let pos = self.position + offset;
        &self.tokens[pos.min(self.tokens.len() - 1)]
    }

    fn advance(&mut self) {
        self.position += 1;
    }

    fn expect(&mut self, expected: TokenType) -> Result<(), String> {
        if std::mem::discriminant(&self.current_token().token_type) == std::mem::discriminant(&expected) {
            self.advance();
            Ok(())
        } else {
            let token = self.current_token();
            Err(format!("{} (line {}, column {}) - unexpected token", 
                self.filename, token.line, token.column))
        }
    }

    fn parse_program(&mut self) -> Result<Vec<Statement>, String> {
        let mut statements = Vec::new();
        while !matches!(self.current_token().token_type, TokenType::Eof) {
            statements.push(self.parse_statement()?);
        }
        Ok(statements)
    }

    fn parse_statement(&mut self) -> Result<Statement, String> {
        match &self.current_token().token_type {
            TokenType::Let => {
                self.advance();
                let name = self.parse_identifier()?;
                self.expect(TokenType::Equal)?;
                let value = self.parse_expression()?;
                Ok(Statement::Let { name, value })
            }
            TokenType::If => {
