use std::env;
use std::fs;
use std::io::{self, BufRead};
use std::process::{self, Command};
use std::collections::HashMap;

// ============ LEXER ============

#[derive(Debug, Clone, PartialEq)]
enum TokenType {
    // Literals
    Number(f64),
    String(String),
    Boolean(bool),
    Nil,

    // Identifiers and keywords
    Identifier(String),
    Let,
    Function,
    End,
    If,
    Then,
    Else,
    For,
    In,
    Do,
    While,
    And,
    Or,
    Not,
    Return,
    True,
    False,

    // Operators
    Plus,
    Minus,
    Star,
    Slash,
    Percent,
    Equal,
    EqualEqual,
    NotEqual,
    Less,
    LessEqual,
    Greater,
    GreaterEqual,
    LeftShell,
    RightShell,
    Pipe,

    // Delimiters
    LeftParen,
    RightParen,
    LeftBracket,
    RightBracket,
    LeftBrace,
    RightBrace,
    Comma,
    Dot,
    Colon,
    Semicolon,

    // Special
    At,
    Dollar,

    // End of file
    Eof,
}

#[derive(Debug, Clone)]
struct Token {
    token_type: TokenType,
    line: usize,
    column: usize,
}

struct Lexer {
    input: Vec<char>,
    position: usize,
    line: usize,
    column: usize,
    filename: String,
}

impl Lexer {
    fn new(input: &str, filename: &str) -> Self {
        Lexer {
            input: input.chars().collect(),
            position: 0,
            line: 1,
            column: 0,
            filename: filename.to_string(),
        }
    }

    fn current_char(&self) -> Option<char> {
        if self.position < self.input.len() {
            Some(self.input[self.position])
        } else {
            None
        }
    }

    fn peek_char(&self, offset: usize) -> Option<char> {
        let pos = self.position + offset;
        if pos < self.input.len() {
            Some(self.input[pos])
        } else {
            None
        }
    }

    fn advance(&mut self) {
        if let Some(ch) = self.current_char() {
            if ch == '\n' {
                self.line += 1;
                self.column = 0;
            } else {
                self.column += 1;
            }
            self.position += 1;
        }
    }

    fn skip_whitespace(&mut self) {
        while let Some(ch) = self.current_char() {
            if ch.is_whitespace() {
                self.advance();
            } else if ch == '#' {
                // Skip comments
                while let Some(c) = self.current_char() {
                    if c == '\n' {
                        break;
                    }
                    self.advance();
                }
            } else {
                break;
            }
        }
    }

    fn read_string(&mut self, quote: char) -> String {
        let mut result = String::new();
        self.advance(); // Skip opening quote

        while let Some(ch) = self.current_char() {
            if ch == quote {
                self.advance();
                break;
            } else if ch == '\\' {
                self.advance();
                match self.current_char() {
                    Some('n') => result.push('\n'),
                    Some('t') => result.push('\t'),
                    Some('r') => result.push('\r'),
                    Some('\\') => result.push('\\'),
                    Some('"') => result.push('"'),
                    Some('\'') => result.push('\''),
                    Some(c) => result.push(c),
                    None => break,
                }
                self.advance();
            } else {
                result.push(ch);
                self.advance();
            }
        }

        result
    }

    fn read_number(&mut self) -> f64 {
        let mut num_str = String::new();

        while let Some(ch) = self.current_char() {
            if ch.is_numeric() || ch == '.' {
                num_str.push(ch);
                self.advance();
            } else {
                break;
            }
        }

        num_str.parse().unwrap_or(0.0)
    }

    fn read_identifier(&mut self) -> String {
        let mut ident = String::new();

        while let Some(ch) = self.current_char() {
            if ch.is_alphanumeric() || ch == '_' {
                ident.push(ch);
                self.advance();
            } else {
                break;
            }
        }

        ident
    }

    fn next_token(&mut self) -> Token {
        self.skip_whitespace();

        let line = self.line;
        let column = self.column;

        let token_type = match self.current_char() {
            None => TokenType::Eof,
            Some('+') => {
                self.advance();
                TokenType::Plus
            }
            Some('-') => {
                self.advance();
                TokenType::Minus
            }
            Some('*') => {
                self.advance();
                TokenType::Star
            }
            Some('/') => {
                self.advance();
                TokenType::Slash
            }
            Some('%') => {
                self.advance();
                TokenType::Percent
            }
            Some('=') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    TokenType::EqualEqual
                } else {
                    TokenType::Equal
                }
            }
            Some('!') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    TokenType::NotEqual
                } else {
                    panic!("Unexpected character '!'");
                }
            }
            Some('<') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    TokenType::LessEqual
                } else if self.current_char() == Some('{') {
                    self.advance();
                    TokenType::LeftShell
                } else {
                    TokenType::Less
                }
            }
            Some('>') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    TokenType::GreaterEqual
                } else if self.current_char() == Some('}') {
                    self.advance();
                    TokenType::RightShell
                } else {
                    TokenType::Greater
                }
            }
            Some('|') => {
                self.advance();
                TokenType::Pipe
            }
            Some('(') => {
                self.advance();
                TokenType::LeftParen
            }
            Some(')') => {
                self.advance();
                TokenType::RightParen
            }
            Some('[') => {
                self.advance();
                TokenType::LeftBracket
            }
            Some(']') => {
                self.advance();
                TokenType::RightBracket
            }
            Some('{') => {
                self.advance();
                TokenType::LeftBrace
            }
            Some('}') => {
                self.advance();
                TokenType::RightBrace
            }
            Some(',') => {
                self.advance();
                TokenType::Comma
            }
            Some('.') => {
                self.advance();
                TokenType::Dot
            }
            Some(':') => {
                self.advance();
                TokenType::Colon
            }
            Some(';') => {
                self.advance();
                TokenType::Semicolon
            }
            Some('@') => {
                self.advance();
                TokenType::At
            }
            Some('$') => {
                self.advance();
                TokenType::Dollar
            }
            Some('"') => {
                let s = self.read_string('"');
                TokenType::String(s)
            }
            Some('\'') => {
                let s = self.read_string('\'');
                TokenType::String(s)
            }
            Some(ch) if ch.is_numeric() => {
                let num = self.read_number();
                TokenType::Number(num)
            }
            Some(ch) if ch.is_alphabetic() || ch == '_' => {
                let ident = self.read_identifier();
                match ident.as_str() {
                    "let" => TokenType::Let,
                    "function" => TokenType::Function,
                    "end" => TokenType::End,
                    "if" => TokenType::If,
                    "then" => TokenType::Then,
                    "else" => TokenType::Else,
                    "for" => TokenType::For,
                    "in" => TokenType::In,
                    "do" => TokenType::Do,
                    "while" => TokenType::While,
                    "and" => TokenType::And,
                    "or" => TokenType::Or,
                    "not" => TokenType::Not,
                    "return" => TokenType::Return,
                    "true" => TokenType::Boolean(true),
                    "false" => TokenType::Boolean(false),
                    "nil" => TokenType::Nil,
                    _ => TokenType::Identifier(ident),
                }
            }
            Some(ch) => {
                panic!("Unexpected character '{}'", ch);
            }
        };

        Token {
            token_type,
            line,
            column,
        }
    }

    fn tokenize(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            let token = self.next_token();
            let is_eof = matches!(token.token_type, TokenType::Eof);
            tokens.push(token);
            if is_eof {
                break;
            }
        }
        tokens
    }
}

// ============ AST ============

#[derive(Debug, Clone)]
enum Expr {
    Number(f64),
    String(String),
    Boolean(bool),
    Nil,
    Identifier(String),
    Array(Vec<Expr>),
    Object(Vec<(String, Expr)>),
    BinaryOp {
        left: Box<Expr>,
        op: String,
        right: Box<Expr>,
    },
    UnaryOp {
        op: String,
        operand: Box<Expr>,
    },
    Call {
        func: Box<Expr>,
        args: Vec<Expr>,
    },
    Index {
        obj: Box<Expr>,
        index: Box<Expr>,
    },
    Field {
        obj: Box<Expr>,
        field: String,
    },
    Function {
        params: Vec<String>,
        body: Vec<Statement>,
    },
    ShellCommand {
        parts: Vec<Expr>,
    },
    IfExpr {
        condition: Box<Expr>,
        then_body: Vec<Statement>,
        else_body: Option<Vec<Statement>>,
    },
}

#[derive(Debug, Clone)]
enum Statement {
    Expression(Expr),
    Let {
        name: String,
        value: Expr,
    },
    Assignment {
        name: String,
        value: Expr,
    },
    If {
        condition: Expr,
        then_body: Vec<Statement>,
        else_body: Option<Vec<Statement>>,
    },
    For {
        var: String,
        iter: Expr,
        body: Vec<Statement>,
    },
    While {
        condition: Expr,
        body: Vec<Statement>,
    },
    Return(Option<Expr>),
}

// ============ PARSER ============

struct Parser {
    tokens: Vec<Token>,
    position: usize,
    filename: String,
}

impl Parser {
    fn new(tokens: Vec<Token>, filename: &str) -> Self {
        Parser {
            tokens,
            position: 0,
            filename: filename.to_string(),
        }
    }

    fn current_token(&self) -> &Token {
        &self.tokens[self.position.min(self.tokens.len() - 1)]
    }

    fn peek_token(&self, offset: usize) -> &Token {
        let pos = self.position + offset;
        &self.tokens[pos.min(self.tokens.len() - 1)]
    }

    fn advance(&mut self) {
        self.position += 1;
    }

    fn expect(&mut self, expected: TokenType) -> Result<(), String> {
        if std::mem::discriminant(&self.current_token().token_type) == std::mem::discriminant(&expected) {
            self.advance();
            Ok(())
        } else {
            let token = self.current_token();
            Err(format!("{} (line {}, column {}) - unexpected token", 
                self.filename, token.line, token.column))
        }
    }

    fn parse_program(&mut self) -> Result<Vec<Statement>, String> {
        let mut statements = Vec::new();
        while !matches!(self.current_token().token_type, TokenType::Eof) {
            statements.push(self.parse_statement()?);
        }
        Ok(statements)
    }

    fn parse_statement(&mut self) -> Result<Statement, String> {
        match &self.current_token().token_type {
            TokenType::Let => {
                self.advance();
                let name = self.parse_identifier()?;
                self.expect(TokenType::Equal)?;
                let value = self.parse_expression()?;
                Ok(Statement::Let { name, value })
            }
            TokenType::If => {
                self.advance();
                let condition = self.parse_expression()?;
                self.expect(TokenType::Then)?;
                let then_body = self.parse_block_until(&[TokenType::Else, TokenType::End])?;

                let else_body = if matches!(self.current_token().token_type, TokenType::Else) {
                    self.advance();
                    Some(self.parse_block_until(&[TokenType::End])?)
                } else {
                    None
                };

                self.expect(TokenType::End)?;
                Ok(Statement::If { condition, then_body, else_body })
            }
            TokenType::For => {
                self.advance();
                let var = self.parse_identifier()?;
                self.expect(TokenType::In)?;
                let iter = self.parse_expression()?;
                self.expect(TokenType::Do)?;
                let body = self.parse_block_until(&[TokenType::End])?;
                self.expect(TokenType::End)?;
                Ok(Statement::For { var, iter, body })
            }
            TokenType::While => {
                self.advance();
                let condition = self.parse_expression()?;
                self.expect(TokenType::Do)?;
                let body = self.parse_block_until(&[TokenType::End])?;
                self.expect(TokenType::End)?;
                Ok(Statement::While { condition, body })
            }
            TokenType::Return => {
                self.advance();
                let value = if matches!(self.current_token().token_type, TokenType::Eof | TokenType::End) {
                    None
                } else {
                    Some(self.parse_expression()?)
                };
                Ok(Statement::Return(value))
            }
            _ => {
                let expr = self.parse_expression()?;
                // Check if this is an assignment
                if let Expr::Identifier(name) = &expr {
                    if matches!(self.current_token().token_type, TokenType::Equal) {
                        self.advance();
                        let value = self.parse_expression()?;
                        return Ok(Statement::Assignment { name: name.clone(), value });
                    }
                }
                Ok(Statement::Expression(expr))
            }
        }
    }

    fn parse_block_until(&mut self, end_tokens: &[TokenType]) -> Result<Vec<Statement>, String> {
        let mut statements = Vec::new();
        while !end_tokens.iter().any(|t| std::mem::discriminant(&self.current_token().token_type) == std::mem::discriminant(t)) 
              && !matches!(self.current_token().token_type, TokenType::Eof) {
            statements.push(self.parse_statement()?);
        }
        Ok(statements)
    }

    fn parse_identifier(&mut self) -> Result<String, String> {
        if let TokenType::Identifier(name) = &self.current_token().token_type {
            let result = name.clone();
            self.advance();
            Ok(result)
        } else {
            Err(format!("Expected identifier"))
        }
    }

    fn parse_expression(&mut self) -> Result<Expr, String> {
        self.parse_or()
    }

    fn parse_or(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_and()?;

        while matches!(self.current_token().token_type, TokenType::Or) {
            self.advance();
            let right = self.parse_and()?;
            left = Expr::BinaryOp {
                left: Box::new(left),
                op: "or".to_string(),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_and(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_equality()?;

        while matches!(self.current_token().token_type, TokenType::And) {
            self.advance();
            let right = self.parse_equality()?;
            left = Expr::BinaryOp {
                left: Box::new(left),
                op: "and".to_string(),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_equality(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_relational()?;

        loop {
            let op = match &self.current_token().token_type {
                TokenType::EqualEqual => "==",
                TokenType::NotEqual => "!=",
                _ => break,
            };
            self.advance();
            let right = self.parse_relational()?;
            left = Expr::BinaryOp {
                left: Box::new(left),
                op: op.to_string(),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_relational(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_additive()?;

        loop {
            let op = match &self.current_token().token_type {
                TokenType::Less => "<",
                TokenType::LessEqual => "<=",
                TokenType::Greater => ">",
                TokenType::GreaterEqual => ">=",
                _ => break,
            };
            self.advance();
            let right = self.parse_additive()?;
            left = Expr::BinaryOp {
                left: Box::new(left),
                op: op.to_string(),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_additive(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_multiplicative()?;

        loop {
            let op = match &self.current_token().token_type {
                TokenType::Plus => "+",
                TokenType::Minus => "-",
                _ => break,
            };
            self.advance();
            let right = self.parse_multiplicative()?;
            left = Expr::BinaryOp {
                left: Box::new(left),
                op: op.to_string(),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_multiplicative(&mut self) -> Result<Expr, String> {
        let mut left = self.parse_unary()?;

        loop {
            let op = match &self.current_token().token_type {
                TokenType::Star => "*",
                TokenType::Slash => "/",
                TokenType::Percent => "%",
                _ => break,
            };
            self.advance();
            let right = self.parse_unary()?;
            left = Expr::BinaryOp {
                left: Box::new(left),
                op: op.to_string(),
                right: Box::new(right),
            };
        }

        Ok(left)
    }

    fn parse_unary(&mut self) -> Result<Expr, String> {
        match &self.current_token().token_type {
            TokenType::Not => {
                self.advance();
                let operand = self.parse_unary()?;
                Ok(Expr::UnaryOp {
                    op: "not".to_string(),
                    operand: Box::new(operand),
                })
            }
            TokenType::Minus => {
                self.advance();
                let operand = self.parse_unary()?;
                Ok(Expr::UnaryOp {
                    op: "-".to_string(),
                    operand: Box::new(operand),
                })
            }
            _ => self.parse_postfix(),
        }
    }

    fn parse_postfix(&mut self) -> Result<Expr, String> {
        let mut expr = self.parse_primary()?;

        loop {
            match &self.current_token().token_type {
                TokenType::LeftParen => {
                    self.advance();
                    let args = self.parse_arguments()?;
                    self.expect(TokenType::RightParen)?;
                    expr = Expr::Call {
                        func: Box::new(expr),
                        args,
                    };
                }
                TokenType::LeftBracket => {
                    self.advance();
                    let index = self.parse_expression()?;
                    self.expect(TokenType::RightBracket)?;
                    expr = Expr::Index {
                        obj: Box::new(expr),
                        index: Box::new(index),
                    };
                }
                TokenType::Dot => {
                    self.advance();
                    let field = self.parse_identifier()?;
                    expr = Expr::Field {
                        obj: Box::new(expr),
                        field,
                    };
                }
                _ => break,
            }
        }

        Ok(expr)
    }

    fn parse_primary(&mut self) -> Result<Expr, String> {
        match &self.current_token().token_type.clone() {
            TokenType::Number(n) => {
                let num = *n;
                self.advance();
                Ok(Expr::Number(num))
            }
            TokenType::String(s) => {
                let string = s.clone();
                self.advance();
                Ok(Expr::String(string))
            }
            TokenType::Boolean(b) => {
                let bool_val = *b;
                self.advance();
                Ok(Expr::Boolean(bool_val))
            }
            TokenType::Nil => {
                self.advance();
                Ok(Expr::Nil)
            }
            TokenType::Identifier(name) => {
                let ident = name.clone();
                self.advance();
                Ok(Expr::Identifier(ident))
            }
            TokenType::LeftBracket => {
                self.advance();
                let mut elements = Vec::new();

                while !matches!(self.current_token().token_type, TokenType::RightBracket | TokenType::Eof) {
                    elements.push(self.parse_expression()?);
                    if matches!(self.current_token().token_type, TokenType::Comma) {
                        self.advance();
                    } else {
                        break;
                    }
                }

                self.expect(TokenType::RightBracket)?;
                Ok(Expr::Array(elements))
            }
            TokenType::At => {
                self.advance();
                self.expect(TokenType::LeftBracket)?;
                let mut fields = Vec::new();

                while !matches!(self.current_token().token_type, TokenType::RightBracket | TokenType::Eof) {
                    let key = self.parse_identifier()?;
                    self.expect(TokenType::Colon)?;
                    let value = self.parse_expression()?;
                    fields.push((key, value));

                    if matches!(self.current_token().token_type, TokenType::Comma) {
                        self.advance();
                    } else {
                        break;
                    }
                }

                self.expect(TokenType::RightBracket)?;
                Ok(Expr::Object(fields))
            }
            TokenType::Function => {
                self.advance();
                self.expect(TokenType::LeftParen)?;
                let params = self.parse_parameters()?;
                self.expect(TokenType::RightParen)?;
                let body = self.parse_block_until(&[TokenType::End])?;
                self.expect(TokenType::End)?;
                Ok(Expr::Function { params, body })
            }
            TokenType::If => {
                self.advance();
                let condition = self.parse_expression()?;
                self.expect(TokenType::Then)?;
                let then_body = self.parse_block_until(&[TokenType::Else, TokenType::End])?;
                let else_body = if matches!(self.current_token().token_type, TokenType::Else) {
                    self.advance();
                    Some(self.parse_block_until(&[TokenType::End])?)
                } else {
                    None
                };
                self.expect(TokenType::End)?;
                Ok(Expr::IfExpr {
                    condition: Box::new(condition),
                    then_body,
                    else_body,
                })
            }
            TokenType::LeftParen => {
                self.advance();
                let expr = self.parse_expression()?;
                self.expect(TokenType::RightParen)?;
                Ok(expr)
            }
            TokenType::Dollar => {
                self.advance();
                self.expect(TokenType::LeftShell)?;
                let parts = self.parse_shell_command()?;
                self.expect(TokenType::RightShell)?;
                Ok(Expr::ShellCommand { parts })
            }
            _ => {
                Err(format!("Unexpected token: {:?}", self.current_token().token_type))
            }
        }
    }

    fn parse_arguments(&mut self) -> Result<Vec<Expr>, String> {
        let mut args = Vec::new();

        while !matches!(self.current_token().token_type, TokenType::RightParen | TokenType::Eof) {
            args.push(self.parse_expression()?);
            if matches!(self.current_token().token_type, TokenType::Comma) {
                self.advance();
            } else {
                break;
            }
        }

        Ok(args)
    }

    fn parse_parameters(&mut self) -> Result<Vec<String>, String> {
        let mut params = Vec::new();

        while !matches!(self.current_token().token_type, TokenType::RightParen | TokenType::Eof) {
            params.push(self.parse_identifier()?);
            if matches!(self.current_token().token_type, TokenType::Comma) {
                self.advance();
            } else {
                break;
            }
        }

        Ok(params)
    }

    fn parse_shell_command(&mut self) -> Result<Vec<Expr>, String> {
        let mut parts = Vec::new();

        while !matches!(self.current_token().token_type, TokenType::RightShell | TokenType::Eof) {
            // For now, parse shell commands as a sequence of identifiers and strings
            match &self.current_token().token_type.clone() {
                TokenType::Identifier(s) => {
                    let ident = s.clone();
                    self.advance();
                    parts.push(Expr::String(ident));
                }
                TokenType::String(s) => {
                    let string = s.clone();
                    self.advance();
                    parts.push(Expr::String(string));
                }
                TokenType::Dollar => {
                    self.advance();
                    let varname = self.parse_identifier()?;
                    parts.push(Expr::Identifier(varname));
                }
                TokenType::Semicolon | TokenType::Pipe => {
                    let op = if matches!(self.current_token().token_type, TokenType::Semicolon) { ";" } else { "|" };
                    self.advance();
                    parts.push(Expr::String(op.to_string()));
                }
                _ => {
                    self.advance();
                }
            }
        }

        Ok(parts)
    }
}

// ============ VALUE ============

#[derive(Debug, Clone)]
enum Value {
    Number(f64),
    String(String),
    Boolean(bool),
    Nil,
    Array(Vec<Value>),
    Object(HashMap<String, Value>),
    Function {
        params: Vec<String>,
        body: Vec<Statement>,
        closure: Environment,
    },
    BuiltinFunction {
        name: String,
        arity: usize,
    },
}

impl Value {
    fn to_string(&self) -> String {
        match self {
            Value::Number(n) => {
                if n.fract() == 0.0 {
                    format!("{}", *n as i64)
                } else {
                    format!("{}", n)
                }
            }
            Value::String(s) => s.clone(),
            Value::Boolean(b) => if *b { "true" } else { "false" }.to_string(),
            Value::Nil => "nil".to_string(),
            Value::Array(arr) => {
                let elements: Vec<String> = arr.iter().map(|v| v.to_string()).collect();
                format!("[ {} ]", elements.join(", "))
            }
            Value::Object(_) => "[object]".to_string(),
            Value::Function { .. } => "[function]".to_string(),
            Value::BuiltinFunction { name, .. } => format!("[builtin {}]", name),
        }
    }

    fn is_truthy(&self) -> bool {
        match self {
            Value::Boolean(b) => *b,
            Value::Nil => false,
            _ => true,
        }
    }
}

// ============ ENVIRONMENT ============

#[derive(Debug, Clone)]
struct Environment {
    vars: HashMap<String, Value>,
    parent: Option<Box<Environment>>,
}

impl Environment {
    fn new() -> Self {
        let mut env = Environment {
            vars: HashMap::new(),
            parent: None,
        };
        env.init_builtins();
        env
    }

    fn with_parent(parent: Environment) -> Self {
        Environment {
            vars: HashMap::new(),
            parent: Some(Box::new(parent)),
        }
    }

    fn init_builtins(&mut self) {
        self.vars.insert("std".to_string(), Value::Object({
            let mut obj = HashMap::new();
            obj.insert("println".to_string(), Value::BuiltinFunction {
                name: "println".to_string(),
                arity: 1,
            });
            obj.insert("len".to_string(), Value::BuiltinFunction {
                name: "len".to_string(),
                arity: 1,
            });
            obj.insert("range".to_string(), Value::BuiltinFunction {
                name: "range".to_string(),
                arity: 3,
            });
            obj.insert("push".to_string(), Value::BuiltinFunction {
                name: "push".to_string(),
                arity: 2,
            });
            obj.insert("pop".to_string(), Value::BuiltinFunction {
                name: "pop".to_string(),
                arity: 1,
            });
            obj.insert("import".to_string(), Value::BuiltinFunction {
                name: "import".to_string(),
                arity: 1,
            });
            obj
        }));
    }

    fn define(&mut self, name: String, value: Value) {
        self.vars.insert(name, value);
    }

    fn get(&self, name: &str) -> Option<Value> {
        if let Some(value) = self.vars.get(name) {
            Some(value.clone())
        } else if let Some(parent) = &self.parent {
            parent.get(name)
        } else {
            None
        }
    }

    fn set(&mut self, name: &str, value: Value) -> Result<(), String> {
        if self.vars.contains_key(name) {
            self.vars.insert(name.to_string(), value);
            Ok(())
        } else if let Some(parent) = &mut self.parent {
            parent.set(name, value)
        } else {
            // In Hush, assignment to undeclared variables is an error
            Err(format!("undeclared variable '{}'", name))
        }
    }
}

// ============ INTERPRETER ============

struct Interpreter {
    env: Environment,
    filename: String,
}

impl Interpreter {
    fn new(filename: &str) -> Self {
        Interpreter {
            env: Environment::new(),
            filename: filename.to_string(),
        }
    }

    fn eval_program(&mut self, statements: Vec<Statement>) -> Result<Value, String> {
        let mut last_value = Value::Nil;
        for stmt in statements {
            last_value = self.eval_statement(stmt)?;
        }
        Ok(last_value)
    }

    fn eval_statement(&mut self, stmt: Statement) -> Result<Value, String> {
        match stmt {
            Statement::Expression(expr) => self.eval_expression(expr),
            Statement::Let { name, value } => {
                let val = self.eval_expression(value)?;
                self.env.define(name, val.clone());
                Ok(val)
            }
            Statement::Assignment { name, value } => {
                let val = self.eval_expression(value)?;
                self.env.set(&name, val.clone())?;
                Ok(val)
            }
            Statement::If { condition, then_body, else_body } => {
                let cond_val = self.eval_expression(condition)?;
                if cond_val.is_truthy() {
                    let mut last = Value::Nil;
                    for stmt in then_body {
                        last = self.eval_statement(stmt)?;
                    }
                    Ok(last)
                } else if let Some(else_stmts) = else_body {
                    let mut last = Value::Nil;
                    for stmt in else_stmts {
                        last = self.eval_statement(stmt)?;
                    }
                    Ok(last)
                } else {
                    Ok(Value::Nil)
                }
            }
            Statement::For { var, iter, body } => {
                let iter_val = self.eval_expression(iter)?;
                let mut last = Value::Nil;

                if let Value::Array(arr) = iter_val {
                    for item in arr {
                        self.env.define(var.clone(), item);
                        for stmt in body.clone() {
                            last = self.eval_statement(stmt)?;
                        }
                    }
                } else {
                    return Err(format!("value ({}) has unexpected type, expected function", iter_val.to_string()));
                }

                Ok(last)
            }
            Statement::While { condition, body } => {
                let mut last = Value::Nil;
                loop {
                    let cond_val = self.eval_expression(condition.clone())?;
                    if !cond_val.is_truthy() {
                        break;
                    }
                    for stmt in body.clone() {
                        last = self.eval_statement(stmt)?;
                    }
                }
                Ok(last)
            }
            Statement::Return(expr) => {
                if let Some(e) = expr {
                    self.eval_expression(e)
                } else {
                    Ok(Value::Nil)
                }
            }
        }
    }

    fn eval_expression(&mut self, expr: Expr) -> Result<Value, String> {
        match expr {
            Expr::Number(n) => Ok(Value::Number(n)),
            Expr::String(s) => Ok(Value::String(s)),
            Expr::Boolean(b) => Ok(Value::Boolean(b)),
            Expr::Nil => Ok(Value::Nil),
            Expr::Identifier(name) => {
                self.env.get(&name).ok_or_else(|| format!("undeclared variable '{}'", name))
            }
            Expr::Array(elements) => {
                let mut values = Vec::new();
                for elem in elements {
                    values.push(self.eval_expression(elem)?);
                }
                Ok(Value::Array(values))
            }
            Expr::Object(fields) => {
                let mut obj = HashMap::new();
                for (key, value_expr) in fields {
                    obj.insert(key, self.eval_expression(value_expr)?);
                }
                Ok(Value::Object(obj))
            }
            Expr::BinaryOp { left, op, right } => {
                let left_val = self.eval_expression(*left)?;
                let right_val = self.eval_expression(*right)?;
                self.apply_binary_op(left_val, &op, right_val)
            }
            Expr::UnaryOp { op, operand } => {
                let val = self.eval_expression(*operand)?;
                match op.as_str() {
                    "not" => Ok(Value::Boolean(!val.is_truthy())),
                    "-" => {
                        if let Value::Number(n) = val {
                            Ok(Value::Number(-n))
                        } else {
                            Err(format!("Cannot negate non-number"))
                        }
                    }
                    _ => Err(format!("Unknown unary operator: {}", op)),
                }
            }
            Expr::Call { func, args } => {
                let func_val = self.eval_expression(*func)?;
                let arg_vals: Result<Vec<_>, _> = args.into_iter().map(|a| self.eval_expression(a)).collect();
                let arg_vals = arg_vals?;
                self.call_function(func_val, arg_vals)
            }
            Expr::Index { obj, index } => {
                let obj_val = self.eval_expression(*obj)?;
                let index_val = self.eval_expression(*index)?;

                match (obj_val, index_val) {
                    (Value::Array(arr), Value::Number(idx)) => {
                        let index = idx as usize;
                        arr.get(index).cloned().ok_or_else(|| format!("index ({}) out of bounds", index))
                    }
                    (Value::Object(map), Value::String(key)) => {
                        map.get(&key).cloned().ok_or_else(|| format!("index (\"{}\") out of bounds", key))
                    }
                    _ => Err(format!("Invalid indexing")),
                }
            }
            Expr::Field { obj, field } => {
                let obj_val = self.eval_expression(*obj)?;
                match obj_val {
                    Value::Object(map) => {
                        map.get(&field).cloned().ok_or_else(|| format!("index (\"{}\") out of bounds", field))
                    }
                    _ => Err(format!("Cannot access field on non-object")),
                }
            }
            Expr::Function { params, body } => {
                Ok(Value::Function {
                    params,
                    body,
                    closure: self.env.clone(),
                })
            }
            Expr::ShellCommand { parts } => {
                let mut cmd_string = String::new();
                for part in parts {
                    match part {
                        Expr::String(s) => {
                            if !cmd_string.is_empty() {
                                cmd_string.push(' ');
                            }
                            cmd_string.push_str(&s);
                        }
                        Expr::Identifier(name) => {
                            if let Some(val) = self.env.get(&name) {
                                if !cmd_string.is_empty() {
                                    cmd_string.push(' ');
                                }
                                cmd_string.push_str(&val.to_string());
                            }
                        }
                        _ => {}
                    }
                }

                let output = Command::new("sh")
                    .arg("-c")
                    .arg(&cmd_string)
                    .output()
                    .map_err(|e| format!("Failed to execute command: {}", e))?;

                let stdout = String::from_utf8_lossy(&output.stdout).to_string();
                let stderr = String::from_utf8_lossy(&output.stderr).to_string();
                let status = output.status.code().unwrap_or(-1) as f64;

                let mut result = HashMap::new();
                result.insert("stdout".to_string(), Value::String(stdout));
                result.insert("stderr".to_string(), Value::String(stderr));
                result.insert("status".to_string(), Value::Number(status));

                Ok(Value::Object(result))
            }
            Expr::IfExpr { condition, then_body, else_body } => {
                let cond_val = self.eval_expression(*condition)?;
                if cond_val.is_truthy() {
                    let mut last = Value::Nil;
                    for stmt in then_body {
                        last = self.eval_statement(stmt)?;
                    }
                    Ok(last)
                } else if let Some(else_stmts) = else_body {
                    let mut last = Value::Nil;
                    for stmt in else_stmts {
                        last = self.eval_statement(stmt)?;
                    }
                    Ok(last)
                } else {
                    Ok(Value::Nil)
                }
            }
        }
    }

    fn apply_binary_op(&self, left: Value, op: &str, right: Value) -> Result<Value, String> {
        match (left, right) {
            (Value::Number(l), Value::Number(r)) => {
                match op {
                    "+" => Ok(Value::Number(l + r)),
                    "-" => Ok(Value::Number(l - r)),
                    "*" => Ok(Value::Number(l * r)),
                    "/" => Ok(Value::Number(l / r)),
                    "%" => Ok(Value::Number(l % r)),
                    "==" => Ok(Value::Boolean((l - r).abs() < f64::EPSILON)),
                    "!=" => Ok(Value::Boolean((l - r).abs() >= f64::EPSILON)),
                    "<" => Ok(Value::Boolean(l < r)),
                    "<=" => Ok(Value::Boolean(l <= r)),
                    ">" => Ok(Value::Boolean(l > r)),
                    ">=" => Ok(Value::Boolean(l >= r)),
                    _ => Err(format!("Unknown operator: {}", op)),
                }
            }
            (Value::String(l), Value::String(r)) => {
                match op {
                    "==" => Ok(Value::Boolean(l == r)),
                    "!=" => Ok(Value::Boolean(l != r)),
                    "<" => Ok(Value::Boolean(l < r)),
                    "<=" => Ok(Value::Boolean(l <= r)),
                    ">" => Ok(Value::Boolean(l > r)),
                    ">=" => Ok(Value::Boolean(l >= r)),
                    _ => Err(format!("Unknown operator: {}", op)),
                }
            }
            (Value::Boolean(l), Value::Boolean(r)) => {
                match op {
                    "and" => Ok(Value::Boolean(l && r)),
                    "or" => Ok(Value::Boolean(l || r)),
                    "==" => Ok(Value::Boolean(l == r)),
                    "!=" => Ok(Value::Boolean(l != r)),
                    _ => Err(format!("Unknown operator: {}", op)),
                }
            }
            (l, r) => {
                match op {
                    "==" => Ok(Value::Boolean(format!("{:?}", l) == format!("{:?}", r))),
                    "!=" => Ok(Value::Boolean(format!("{:?}", l) != format!("{:?}", r))),
                    "and" => Ok(Value::Boolean(l.is_truthy() && r.is_truthy())),
                    "or" => Ok(Value::Boolean(l.is_truthy() || r.is_truthy())),
                    _ => Err(format!("Unknown operator: {}", op)),
                }
            }
        }
    }

    fn call_function(&mut self, func: Value, args: Vec<Value>) -> Result<Value, String> {
        match func {
            Value::Function { params, body, closure } => {
                if params.len() != args.len() {
                    return Err(format!("Function expects {} arguments, got {}", params.len(), args.len()));
                }

                let mut new_env = Environment::with_parent(closure);
                for (param, arg) in params.iter().zip(args.iter()) {
                    new_env.define(param.clone(), arg.clone());
                }

                let old_env = std::mem::replace(&mut self.env, new_env);
                let mut last = Value::Nil;
                for stmt in body {
                    last = self.eval_statement(stmt)?;
                }
                self.env = old_env;
                Ok(last)
            }
            Value::BuiltinFunction { name, .. } => {
                self.call_builtin(&name, args)
            }
            _ => Err(format!("Cannot call non-function")),
        }
    }

    fn call_builtin(&mut self, name: &str, args: Vec<Value>) -> Result<Value, String> {
        match name {
            "println" => {
                for arg in args {
                    println!("{}", arg.to_string());
                }
                Ok(Value::Nil)
            }
            "len" => {
                if args.len() != 1 {
                    return Err(format!("len expects 1 argument"));
                }
                match &args[0] {
                    Value::Array(arr) => Ok(Value::Number(arr.len() as f64)),
                    Value::String(s) => Ok(Value::Number(s.len() as f64)),
                    Value::Object(map) => Ok(Value::Number(map.len() as f64)),
                    _ => Err(format!("len expects array or string")),
                }
            }
            "range" => {
                if args.len() != 3 {
                    return Err(format!("range expects 3 arguments"));
                }
                let start = match &args[0] {
                    Value::Number(n) => *n as i64,
                    _ => return Err("range start must be number".to_string()),
                };
                let end = match &args[1] {
                    Value::Number(n) => *n as i64,
                    _ => return Err("range end must be number".to_string()),
                };
                let step = match &args[2] {
                    Value::Number(n) => *n as i64,
                    _ => return Err("range step must be number".to_string()),
                };

                let mut result = Vec::new();
                if step > 0 {
                    let mut i = start;
                    while i <= end {
                        result.push(Value::Number(i as f64));
                        i += step;
                    }
                } else if step < 0 {
                    let mut i = start;
                    while i >= end {
                        result.push(Value::Number(i as f64));
                        i += step;
                    }
                }
                Ok(Value::Array(result))
            }
            "push" => {
                if args.len() != 2 {
                    return Err(format!("push expects 2 arguments"));
                }
                match &args[0] {
                    Value::Array(arr) => {
                        let mut new_arr = arr.clone();
                        new_arr.push(args[1].clone());
                        Ok(Value::Array(new_arr))
                    }
                    _ => Err(format!("push expects array")),
                }
            }
            "pop" => {
                if args.len() != 1 {
                    return Err(format!("pop expects 1 argument"));
                }
                match &args[0] {
                    Value::Array(arr) => {
                        if arr.is_empty() {
                            Ok(Value::Nil)
                        } else {
                            Ok(arr[arr.len() - 1].clone())
                        }
                    }
                    _ => Err(format!("pop expects array")),
                }
            }
            "import" => {
                if args.len() != 1 {
                    return Err(format!("import expects 1 argument"));
                }
                match &args[0] {
                    Value::String(_path) => {
                        // For now, just return nil
                        // TODO: Implement file loading
                        Ok(Value::Nil)
                    }
                    _ => Err(format!("import expects string")),
                }
            }
            _ => Err(format!("Unknown builtin function: {}", name)),
        }
    }
}

