fn main() {
    let args: Vec<String> = env::args().collect();

    if args.len() < 2 {
        eprintln!("Hush 0.1.4");
        eprintln!("gahag <gabriel.s.b@live.com>");
        eprintln!("Hush is a unix shell scripting language based on the Lua programming language");
        eprintln!();
        eprintln!("USAGE:");
        eprintln!("    executable [FLAGS] [arguments]...");
        eprintln!();
        eprintln!("FLAGS:");
        eprintln!("        --ast        Print the AST");
        eprintln!("        --check      Perform only static analysis instead of executing.");
        eprintln!("    -h, --help       Prints help information");
        eprintln!("        --lex        Print the lexemes");
        eprintln!("        --program    Print the PROGAM");
        eprintln!("    -V, --version    Prints version information");
        eprintln!();
        eprintln!("ARGS:");
        eprintln!("    <arguments>...    Script and/or arguments");
        process::exit(1);
    }

    let mut flags_done = false;
    let mut show_lex = false;
    let mut show_ast = false;
    let mut show_program = false;
    let mut check_only = false;
    let mut script_file = None;
    let mut _script_args = Vec::new();

    for arg in &args[1..] {
        if !flags_done && arg.starts_with("--") {
            match arg.as_str() {
                "--lex" => show_lex = true,
                "--ast" => show_ast = true,
                "--program" => show_program = true,
                "--check" => check_only = true,
                "--help" | "-h" => {
                    eprintln!("Hush 0.1.4");
                    eprintln!("gahag <gabriel.s.b@live.com>");
                    eprintln!("Hush is a unix shell scripting language based on the Lua programming language");
                    eprintln!();
                    eprintln!("USAGE:");
                    eprintln!("    executable [FLAGS] [arguments]...");
                    eprintln!();
                    eprintln!("FLAGS:");
                    eprintln!("        --ast        Print the AST");
                    eprintln!("        --check      Perform only static analysis instead of executing.");
                    eprintln!("    -h, --help       Prints help information");
                    eprintln!("        --lex        Print the lexemes");
                    eprintln!("        --program    Print the PROGAM");
                    eprintln!("    -V, --version    Prints version information");
                    eprintln!();
                    eprintln!("ARGS:");
                    eprintln!("    <arguments>...    Script and/or arguments");
                    process::exit(0);
                }
                "--version" | "-V" => {
                    eprintln!("Hush 0.1.4");
                    process::exit(0);
                }
                _ => {
                    eprintln!("Unknown flag: {}", arg);
                    process::exit(1);
                }
            }
        } else {
            flags_done = true;
            if script_file.is_none() {
                script_file = Some(arg.clone());
            } else {
                _script_args.push(arg.clone());
            }
        }
    }

    let filename = script_file.unwrap_or_else(|| "<stdin>".to_string());
    let source = if filename == "<stdin>" {
        let stdin = io::stdin();
        let mut input = String::new();
        stdin.lock().read_line(&mut input).expect("Failed to read from stdin");
        input
    } else {
        fs::read_to_string(&filename).unwrap_or_else(|_| {
            eprintln!("Error: Cannot read file '{}'", filename);
            process::exit(1);
        })
    };

    let mut lexer = Lexer::new(&source, &filename);
    let tokens = lexer.tokenize();

    if show_lex {
        println!("--------------------------------------------------");
        for token in &tokens {
            println!("{} (line {}, column {}):\t{:?}", 
                filename, token.line, token.column, token.token_type);
        }
        println!("--------------------------------------------------");
        return;
    }

    let mut parser = Parser::new(tokens, &filename);
    match parser.parse_program() {
        Ok(program) => {
            if show_ast || show_program {
                println!("--------------------------------------------------");
                println!("AST for {}", filename);
                println!("{}", source);
                println!("--------------------------------------------------");
                return;
            }

            if !check_only {
                let mut interpreter = Interpreter::new(&filename);
                match interpreter.eval_program(program) {
                    Ok(_) => {
                        process::exit(0);
                    }
                    Err(e) => {
                        if e.contains("Panic") {
                            eprintln!("Panic in {}: {}", filename, e);
                        } else {
                            eprintln!("Error: {} - {}", filename, e);
                        }
                        process::exit(2);
                    }
                }
            }
        }
        Err(e) => {
            eprintln!("Error: {} - {}", filename, e);
            process::exit(2);
        }
    }
}
