                    self.advance();
                    TokenType::LessEqual
                } else if self.current_char() == Some('{') {
                    self.advance();
                    TokenType::LeftShell
                } else {
                    TokenType::Less
                }
            }
            Some('>') => {
                self.advance();
                if self.current_char() == Some('=') {
                    self.advance();
                    TokenType::GreaterEqual
                } else if self.current_char() == Some('}') {
                    self.advance();
                    TokenType::RightShell
                } else {
                    TokenType::Greater
                }
            }
            Some('|') => {
                self.advance();
                TokenType::Pipe
            }
            Some('(') => {
                self.advance();
