            }
            Some(')') => {
                self.advance();
                TokenType::RightParen
            }
            Some('[') => {
                self.advance();
                TokenType::LeftBracket
            }
            Some(']') => {
                self.advance();
                TokenType::RightBracket
            }
            Some('{') => {
                self.advance();
                TokenType::LeftBrace
            }
            Some('}') => {
                self.advance();
                TokenType::RightBrace
            }
            Some(',') => {
                self.advance();
                TokenType::Comma
            }
            Some('.') => {
                self.advance();
                TokenType::Dot
            }
            Some(':') => {
                self.advance();
                TokenType::Colon
            }
            Some(';') => {
                self.advance();
                TokenType::Semicolon
            }
