                    "function" => TokenType::Function,
                    "end" => TokenType::End,
                    "if" => TokenType::If,
                    "then" => TokenType::Then,
                    "else" => TokenType::Else,
                    "for" => TokenType::For,
                    "in" => TokenType::In,
                    "do" => TokenType::Do,
                    "while" => TokenType::While,
                    "and" => TokenType::And,
                    "or" => TokenType::Or,
                    "not" => TokenType::Not,
                    "return" => TokenType::Return,
                    "true" => TokenType::Boolean(true),
                    "false" => TokenType::Boolean(false),
                    "nil" => TokenType::Nil,
                    _ => TokenType::Identifier(ident),
