            }
        };

        Token {
            token_type,
            line,
            column,
        }
    }

    fn tokenize(&mut self) -> Vec<Token> {
        let mut tokens = Vec::new();
        loop {
            let token = self.next_token();
            let is_eof = matches!(token.token_type, TokenType::Eof);
            tokens.push(token);
            if is_eof {
                break;
            }
        }
        tokens
    }
}

// ============ AST ============

#[derive(Debug, Clone)]
enum Expr {
    Number(f64),
    String(String),
    Boolean(bool),
    Nil,
    Identifier(String),
    Array(Vec<Expr>),
    Object(Vec<(String, Expr)>),
    BinaryOp {
